    {"reference_id": "R1", "candidate_id": "C1", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "He is supposed to be standing and he begins to walk and continues to walk throughout the clip.", "candidate_evidence": "The person's legs and feet undergo unnatural morphing and blending with the snowy ground while walking.", "basis": "explicit_separation", "reason_ko": "기준은 인물이 서 있어야 함에도 걷기 시작하는 동작 자체의 프롬프트 불일치를 지적하지만, 후보는 보행 중 다리와 발이 눈 덮인 바닥과 융합되는 시각적 모핑 왜곡을 문제 삼고 있어 서로 다른 상호작용 및 현상입니다.", "separation_basis": "different_interaction"},
    {"reference_id": "R1", "candidate_id": "C2", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "He is supposed to be standing and he begins to walk and continues to walk throughout the clip.", "candidate_evidence": "Legs and clothing morph irregularly while walking, blending into dark trousers without clear footprints.", "basis": "explicit_separation", "reason_ko": "기준은 서 있는 대신 보행을 계속하는 행동 수행의 불일치를 지적하는 반면, 후보는 보행 도중 다리와 옷의 불규칙한 모핑 및 발자국 부재 등 시각적 렌더링 왜곡을 지적하므로 명확히 분리되는 결함입니다.", "separation_basis": "different_interaction"},
    {"reference_id": "R1", "candidate_id": "C3", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "He is supposed to be standing and he begins to walk and continues to walk throughout the clip.", "candidate_evidence": "The brown cloak exhibits unstable shifting textures and floating folds that lack consistent physical movement.", "basis": "explicit_separation", "reason_ko": "기준은 인물의 전신 행동(서 있어야 하는데 걸음)에 대한 불일치인 반면, 후보는 갈색 망토 텍스처와 주름의 비물리적 불안정성을 지적하여 대상 부위와 문제 현상이 전혀 다릅니다.", "separation_basis": "different_entity"},
    {"reference_id": "R1", "candidate_id": "C4", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "He is supposed to be standing and he begins to walk and continues to walk throughout the clip.", "candidate_evidence": "프롬프트에서는 오스트레일리아 원주민을 요구했으나 영상에는 백인 남성이 나타납니다.", "basis": "explicit_separation", "reason_ko": "기준은 인물이 서 있지 않고 걷는 동작/행동 불일치를 기술하고 있으나, 후보는 요구된 인종(오스트레일리아 원주민) 대신 백인 남성이 나타났다는 인물 정체성/외양 불일치를 지적하므로 상이한 불일치 사건입니다.", "separation_basis": "distinct_occurrence"}
  ]
}

